#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "../common/sha256.h"
static int okright(const char*s){return !strcmp(s,"authorized")||!strcmp(s,"redistribution_approved")||!strcmp(s,"public_domain")||!strcmp(s,"original_homebrew");}
static int get(const char*j,const char*k,char*v,size_t cap){char key[80];const char*p,*e;snprintf(key,sizeof key,"\"%s\"",k);p=strstr(j,key);if(!p)return 0;p=strchr(p,':')+1;while(*p==' '||*p=='\n'||*p=='\t')p++;if(*p=='"'){p++;e=strchr(p,'"');}else e=strpbrk(p,",}\n");if(!e||(size_t)(e-p)>=cap)return 0;memcpy(v,p,(size_t)(e-p));v[e-p]=0;return 1;}
int main(int ac,char**av){char hash[65],rhs[80]="unknown",v[128],sizebuf[64];uint64_t size,actual;int i,red=0;const char*title="",*platform="",*prov="",*fmt="unknown";FILE*f;if(ac>=2&&!strcmp(av[1],"create")){if(ac<4){fprintf(stderr,"usage: rom-manifest-c create IMAGE OUTPUT --title T --platform P --provenance TEXT [--format F] [--rights-status STATUS] [--redistribution-allowed]\n");return 2;}for(i=4;i<ac;i++){if(!strcmp(av[i],"--title")&&i+1<ac)title=av[++i];else if(!strcmp(av[i],"--platform")&&i+1<ac)platform=av[++i];else if(!strcmp(av[i],"--provenance")&&i+1<ac)prov=av[++i];else if(!strcmp(av[i],"--format")&&i+1<ac)fmt=av[++i];else if(!strcmp(av[i],"--rights-status")&&i+1<ac)snprintf(rhs,sizeof rhs,"%s",av[++i]);else if(!strcmp(av[i],"--redistribution-allowed"))red=1;else{fprintf(stderr,"unknown argument %s\n",av[i]);return 2;}}if(!*title||!*platform||!*prov)return 2;if(red&&!okright(rhs)){fprintf(stderr,"error: redistribution_allowed conflicts with rights_status\n");return 2;}if(!nsha_file(av[2],hash,&size)){perror(av[2]);return 2;}f=fopen(av[3],"w");if(!f){perror(av[3]);return 2;}fprintf(f,"{\n \"schema_version\": 1,\n \"title\": \"%s\",\n \"platform\": \"%s\",\n \"format\": \"%s\",\n \"size_bytes\": %llu,\n \"sha256\": \"%s\",\n \"provenance\": \"%s\",\n \"rights_status\": \"%s\",\n \"redistribution_allowed\": %s\n}\n",title,platform,fmt,(unsigned long long)size,hash,prov,rhs,red?"true":"false");if(fclose(f))return 2;printf("manifest written; SHA-256 %s\n",hash);return 0;}if(ac==4&&!strcmp(av[1],"verify")){long n;char*j;f=fopen(av[2],"rb");if(!f){perror(av[2]);return 2;}fseek(f,0,SEEK_END);n=ftell(f);rewind(f);j=(char*)malloc((size_t)n+1);if(!j)return 2;if(fread(j,1,(size_t)n,f)!=(size_t)n){free(j);fclose(f);return 2;}j[n]=0;fclose(f);if(!get(j,"sha256",v,sizeof v)||!get(j,"size_bytes",sizebuf,sizeof sizebuf)){free(j);puts("FAIL: missing required field");return 1;}if(!nsha_file(av[3],hash,&actual)){free(j);perror(av[3]);return 2;}if(strtoull(sizebuf,NULL,10)!=actual){free(j);puts("FAIL: size mismatch");return 1;}if(strcmp(v,hash)){free(j);puts("FAIL: sha256 mismatch");return 1;}free(j);puts("PASS: image matches manifest");return 0;}fprintf(stderr,"usage: rom-manifest-c create|verify ...\n");return 2;}
